UPDATE companies SET description='Ruben Custom Sawmill and Woodworks, LLC operates from White Bear Township, Minnesota, in the Twin Cities metro area. What started as a weekend passion has grown into a full-time, family-run business serving clients across the region.

The shop produces custom furniture including live-edge tables, bar tops, and mantles, as well as butcher-block-style walnut countertops. In addition to finished pieces, Ruben Custom Sawmill offers portable on-site milling services, bringing a Wood-Mizer sawmill directly to a client''s property to process logs into kiln-dried slabs and native hardwood lumber available by appointment. The company reports having salvaged over 1,000 trees and completed projects for more than 1,000 clients.

Ruben emphasizes care, craftsmanship, and character in every job, whether milling on a client''s property or building a dining table in the shop. The founder''s original mission — giving fallen trees a second life — remains the guiding principle, and the portable milling capability allows customers to preserve trees that hold personal significance.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom furniture manufacturing", "Live-edge table fabrication", "Bar top and mantle fabrication", "Custom walnut countertop fabrication", "Portable on-site sawmilling", "Kiln-dried lumber production", "Native hardwood supply"], "industries": ["Residential", "Custom furniture", "Woodworking", "Lumber milling", "Countertop fabrication"], "materials": ["Salvaged wood", "Native hardwoods", "Walnut", "Cherry", "Burr oak"], "equipment": ["Wood-Mizer Portable Sawmill"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Portable on-site milling with Wood-Mizer sawmill", "Kiln-dried slabs and native hardwoods by appointment", "Custom furniture built from client''s own trees", "Family-run operation founded in 2018", "Over 1,000 trees salvaged and 1,000+ clients served"], "facts_used": ["Founded by Matt Ruben in 2018 -> db", "Headquarters in White Bear Township, Minnesota -> db", "Family-run business -> /", "Custom furniture: tables, bar tops, mantles -> /", "Custom walnut countertops -> /", "Portable on-site milling with Wood-Mizer sawmill -> /", "Kiln-dried slabs and native hardwoods by appointment -> /", "Over 1,000 trees salvaged -> /", "Over 1,000 happy clients -> /", "Materials: walnut, cherry, burr oak -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We craft timeless furniture, countertops, and kiln-dried lumber from locally salvaged wood.", "founded_year": "2018", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='ruben-custom-sawmill-and-woodworks-llc' AND approved AND profile IS NULL;
UPDATE companies SET description='Rustic Log Furniture of Utah, Inc. is based in Orem, Utah. The company was founded in the summer of 1997 by Randy Jackson, who began producing log porch swings. In early 1998, his brother Rodney Jackson joined the venture, and the operation expanded from a single product to a full line of log furniture and cabin decor.

The company manufactures log furniture and related cabin-style products, offering well over a thousand distinct items across categories such as bedroom, dining, living room, office, outdoor, bars and game room, cabinets, accessories, and décor. In addition to log furniture, they produce complementary lines including bedding, metal works, wood carvings and burnings, photography, and metal and antler chandeliers. They maintain in-stock inventory for quick fulfillment and also accept custom-built orders. Products are shipped throughout the United States, Canada, and Europe.

Rustic Log Furniture serves residential customers as well as commercial and entertainment clients. Their furniture has been installed in professional establishments such as the Community Center in Cedar Hills, Utah, and Vacation Marriott properties in Park City, Utah, and South Lake Tahoe. Hollywood productions have used their pieces, including Warner Brothers'' film "Unaccompanied Minors" and Paramount''s series "Yellowstone." Theatrical venues such as the Hale Center Theater in Orem have also featured their products.

The company emphasizes unique designs, a large selection, continuous product improvement, and competitive pricing. They highlight personalized, honest customer service and a commitment to long-term relationships beyond the initial sale. Environmental responsibility is also cited as a core value, with ongoing efforts to reduce waste and preserve natural resources.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Log furniture manufacturing", "Custom furniture building", "Wood carving", "Wood burning", "Metal fabrication", "Chandelier assembly"], "industries": ["Residential furniture", "Hospitality", "Film and television production", "Theater and stage production", "Commercial furniture"], "materials": ["Logs", "Metal", "Antler"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Unique designs, large selection, continuous product improvement, and competitive pricing", "Personalized, honest customer service with long-term relationship focus", "Environmental responsibility and waste reduction efforts", "Products featured in major film, television, and theater productions", "In-stock inventory available for quick fulfillment"], "facts_used": ["Founded 1997 by Randy Jackson -> /about-us", "Joined by brother Rodney in 1998 -> /about-us", "Over a thousand products offered -> /about-us", "Ships to all 50 states, Canada, Europe -> /about-us", "Furnished Community Center in Cedar Hills, UT -> /about-us", "Furnished Vacation Marriotts in Park City and South Lake Tahoe -> /about-us", "Products used in Warner Brothers'' Unaccompanied Minors and Paramount''s Yellowstone -> /about-us", "Products featured at Hale Center Theater in Orem, UT -> /about-us", "Offers bedding, metal works, wood carvings, photography, metal and antler chandeliers -> /about-us", "Family-owned (Jackson family) -> /about-us", "Headquarters Orem, Utah -> db", "Custom built items offered -> /", "Product categories: Accessories, Bars and Game Room, Bedroom, Cabinets, Dining Room, Living Room, Office, Outdoor, D\u00e9cor -> /", "In-stock inventory available -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "In the summer of 1997, young entrepreneur, Randy Jackson, began producing log porch swings.", "founded_year": "1997", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='rustic-log-furniture-of-utah-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Rustic Montana Furniture operates from Philipsburg, Montana, where it has been producing handcrafted western furniture for over two decades. While the exact founding year is not publicly disclosed, the firm emphasizes its Montana roots and a commitment to traditional joinery.

The company designs and builds a range of authentic western furniture, including beds, end tables, console tables, dressers, chests, vanities, dining tables, benches, and outdoor swings. All beds feature true mortise-and-tenon construction, and each piece is handcrafted from either barnwood or log materials. Dining tables are made from reclaimed lumber, resulting in one-of-a-kind surfaces. Production takes place entirely in Montana, though the facility size and employee count are not disclosed.

The company serves residential customers seeking elegantly western furnishings, though specific industry segments or commercial clients are not detailed in its public materials. Its certified "Made in Montana" designation underscores a local manufacturing focus.

Rustic Montana Furniture distinguishes itself through its certified "Made in Montana" status, the use of mortise-and-tenon joinery on all beds, and the creation of unique dining tables from reclaimed lumber. The firm states that each piece is created to last a lifetime, reflecting a philosophy of durability and authentic craftsmanship.', certifications=ARRAY['Made in Montana']::text[], profile='{"capabilities": ["Reclaimed Barnwood Beds", "Log Furniture", "Reclaimed Wood Dining Tables", "Rustic Outdoor Swings", "Mortise and Tenon Construction", "Handcrafted Furniture Manufacturing", "Custom Furniture Design", "Reclaimed Lumber Processing", "Barnwood Furniture", "Western Furniture Production"], "industries": [], "materials": ["Barnwood", "Log", "Reclaimed Lumber"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Certified ''Made in Montana''", "True mortise-and-tenon construction on all beds", "One-of-a-kind dining tables from reclaimed lumber", "Handcrafted from barnwood or log", "Over 20 years of custom furniture experience"], "facts_used": ["Headquarters in Philipsburg, Montana -> db", "Operating for over 20 years -> /about", "Contact person Walter Stanghill -> /about", "Certified ''Made in Montana'' -> /", "Products include beds, end tables, console tables, dressers, chests, vanities, dining tables, benches, outdoor swings -> /", "Mortise and tenon construction on all beds -> /", "Materials: barnwood, log, reclaimed lumber -> /", "One-of-a-kind dining tables from reclaimed lumber -> /", "Handcrafted in Montana -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We design and build authentic mortise & tenon furniture, all in Montana.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='rustic-montana-furniture' AND approved AND profile IS NULL;
UPDATE companies SET description='Rustic Timbers Furniture Co. operates from Branson West, Missouri, along Highway 76 in the Ozarks region. The company describes itself as an "Ozarks Original," though its founding year and ownership structure are not publicly disclosed.

