UPDATE companies SET description='S and Y Industries is based in Winfield, Kansas. The company was founded in 1984 by Sandy Foust on the back porch of a farmhouse in Atlanta, Kansas. It remains family-owned and woman-owned, with Sandy Foust serving as CEO and her sons Dan and John Foust overseeing production and sales.

The company provides custom electronic contract manufacturing services, including printed circuit board (PCB) assembly with surface mount technology (SMT) and thru-hole processes, wire harness assembly, electro-mechanical box builds, product testing, engineering and design, and program management. Operations are housed in a 60,000-square-foot facility staffed by over 100 employees, supporting low- to mid-volume production runs.

S and Y serves customers in medical, aerospace, commercial, and industrial manufacturing sectors. Its client base includes companies requiring ITAR-compliant defense work and ISO 13485-certified medical device production.

The company emphasizes a family-like culture and a commitment to acting as an extension of its customers'' operations, with a stated philosophy of delivering what customers want, when they want it. Certifications such as AS9100D, ISO 9001:2015, ISO 13485, and in-house IPC-A-610 and J-STD-001 qualified personnel underpin its quality focus.', certifications=ARRAY['ISO 9001:2015','ISO 13485','AS9100D','ITAR Registered','IPC-A-610','J-STD-001','ROHS']::text[], profile='{"capabilities": ["PCB assembly (SMT and thru-hole)", "Wire harness assembly", "Electro-mechanical box build", "Product test development and functional testing", "Engineering & design services (DFM, DFT, hardware/software development)", "Program management & inventory solutions", "Material procurement and supply chain management", "Incoming, in-process, and final inspection", "3D Automated Optical Inspection", "IPC-A-610 certified inspection", "J-STD-001 certified soldering", "Custom electronic prototyping", "New product introduction and implementation", "Turnkey electronics manufacturing solutions"], "industries": ["Medical", "Aerospace", "Commercial", "Industrial manufacturing"], "materials": [], "equipment": ["3D Automated Optical Inspection systems"], "volume": "Low- to mid-volume production runs", "lead_time": "", "tolerances": "", "built_on": ["ITAR registered for defense work", "AS9100D certified for aerospace precision", "ISO 13485 certified for medical devices", "In-house IPC-A-610 and J-STD-001 certified technicians", "Family-owned with over 100 employees and 60,000 sq ft facility"], "facts_used": ["Founded 1984 -> /about-us", "Founder Sandy Foust started on back porch -> /about-us", "Family-owned and woman-owned -> /about-us, /quality", "CEO Sandy Foust, sons Dan and John Foust -> /about-us", "Relocated to Winfield, Kansas in 1989 -> /about-us", "60,000 sq ft facility -> /about-us", "Over 100 employees -> /about-us", "Custom electronic contract manufacturing services -> /about-us, /services", "PCB assembly (SMT and thru-hole) -> /services", "Wire harness assembly -> /about-us, /services", "Electro-mechanical box builds -> /about-us, /services", "Product test development and functional testing -> /, /services", "Engineering & design services (DFM, DFT, hardware/software) -> /services", "Program management & inventory solutions -> /services", "Material procurement and supply chain management -> /", "Incoming, in-process, final inspections by IPC-A-610 certified operators -> /services", "3D Automated Optical Inspection systems -> /services", "IPC-A-610 certified technicians -> /quality", "J-STD-001 certified technicians -> /quality", "ISO 9001:2015 certified -> /quality", "ISO 13485 certified -> /quality", "AS9100D certified -> /quality", "ITAR Registered -> /quality", "Industries: medical, aerospace, commercial, industrial manufacturing -> /about-us", "Low- to mid-volume production runs -> /services", "Family-like culture and customer extension philosophy -> /about-us, /services", "Quote: ''We don''t ask questions; we simply give them what they want, when they want it'' -> /services"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Today, the company provides custom electronic contract manufacturing services for printed circuit board (PCB) assembly, wire harness assembly, as well as electro-mechanical box builds and other turnkey electronics solutions.", "founded_year": "1984", "employee_count": "over 100", "cage_code": "", "min_order": "", "export_compliance": ["ITAR registered"], "languages": [], "social_links": [], "ownership_tags": ["Family-owned", "Woman-owned"]}'::jsonb, updated_at=now() WHERE slug='s-and-y-industries-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='S&F Foods, Inc. is a frozen food manufacturer headquartered in Romulus, Michigan, founded in 2003. The company specializes in producing enrobed and topped items for institutional school foodservice programs and retail markets nationwide.

The company operates a 37,000-square-foot facility capable of high- and low-volume production. Its enrobed line fills and par-bakes hand-held pocket items, mixes hot or cold sauces, and individually quick-freezes (IQF) products with multiple packing options including printed film, retail boxes, and cartons. A topped line handles crusts of any size with similar sauce mixing and IQF capabilities. S&F also runs a dedicated gluten-free line with segregated storage, certified suppliers, and in-house and external allergen testing. Product offerings include the Original Pull-A-Part Topped Breadsticks and Dave’s Detroit Style Pizza, and the firm processes USDA commodities such as cheese, tomato paste, and flour.

S&F Foods serves institutional school foodservice programs, including the National School Lunch Program, and retail channels nationwide. Its products are distributed to schools and retail outlets across the country.

The company emphasizes food safety and quality, holding BRCGS AA Grade certification, USDA compliance, gluten-free certification from GFCO, and organic certification from Global Organic Alliance. Its mission highlights decades of experience producing safe, certified, and authentic products with ongoing reviews of food safety policies.', certifications=ARRAY['BRCGS AA Grade','GFCO Gluten-Free','Global Organic Alliance Organic']::text[], profile='{"capabilities": ["Enrobed line (fill and par-bake hand-held items, sauce mixing, IQF, packing)", "Topped line (crust topping and par-baking, sauce mixing, IQF)", "Gluten-free manufacturing (segregated storage, dedicated line, allergen testing)", "USDA commodity processing (cheese, tomato paste, flour)", "IQF freezing", "Sauce mixing (hot/cold)", "Packing (printed film, retail box, carton)"], "industries": ["Institutional school foodservice", "Retail food", "National School Lunch Program"], "materials": ["Cheese", "Tomato paste", "Flour"], "equipment": ["Enrobed production line", "Topped production line", "IQF freezing equipment"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["BRCGS AA Grade certification", "Dedicated gluten-free manufacturing line with segregated storage and allergen testing", "USDA commodity processing for cheese, tomato paste, and flour", "37,000 sq ft facility with high/low volume capacity", "Enrobed and topped product lines with IQF freezing"], "facts_used": ["Founded 2003 -> db", "Headquartered in Romulus, Michigan -> /", "37,000 sq ft facility -> /capabilities", "BRCGS AA Grade certification -> /capabilities", "Enrobed and topped lines -> /capabilities", "Gluten-free manufacturing with segregated storage -> /capabilities", "USDA commodity processing -> /capabilities", "Serves National School Lunch Programs -> /", "Products include Pull-A-Part Breadsticks and Dave''s Detroit Style Pizza -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Manufacturing for institutional school foodservice programs and retail since 2003.", "founded_year": "2003", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='s-f-foods-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='S&W Foods operates from Hammond, Louisiana, where it was founded in 1978 by Frank and Rosemary Spalitta. The family-owned business began by serving foodservice operators throughout Tangipahoa Parish and has since expanded across Southeast Louisiana and the Mississippi Gulf Coast under the leadership of their son, Paul Spalitta, who now serves as president and owner.

The company functions as a broadline distributor, offering a vast selection of food and non‑food items that includes produce, meats, breads, condiments, equipment, smallwares, paper goods, and cleaning supplies. Its distribution facility sits near the I‑55/I‑12 corridor, enabling rapid delivery — notably remaining operational the day after Hurricanes Ida and Katrina. S&W also develops private‑label brands such as Copper Creek Cattle Company and Captain Frank’s Seafood, and runs special programs for custom‑cut steaks, fresh produce through Fresh Concepts, and artisanal cheeses via The Rind Cheese Company.

S&W serves a wide range of restaurant types, from donut shops and coffee shops to Tex‑Mex, Italian, Mediterranean, family dining, sandwich shops, and seafood establishments. Its customer base includes both independent operators and chain accounts, all supported by the company’s independent structure and partnerships with major suppliers like Unipro Foodservice, Campbell Foodservice, ConAgra Foodservice, Rich Products, Pillsbury, Hormel, General Mills, and Smithfield Foods.

The company’s guiding principle, coined by the founder, is "Large enough to serve, small enough to care." This philosophy drives its emphasis on personal relationships, quick reaction to customer needs without corporate red tape, and a commitment to helping operators grow their businesses. The combination of local ownership, disaster‑ready logistics, and curated product programs sets S&W apart in the regional foodservice market.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Broadline foodservice distribution", "Private label branding", "Custom\u2011cut steak program", "Fresh produce program", "Artisanal cheese program", "Online ordering", "Disaster response delivery", "Purchasing power through Unipro Foodservice partnership"], "industries": ["Restaurants", "Donut shops", "Coffee shops", "Tex\u2011Mex restaurants", "Italian restaurants", "Mediterranean restaurants", "Family dining", "Sandwich shops", "Seafood restaurants", "Independent foodservice operators", "Chain foodservice operators"], "materials": ["Fresh produce", "Meats", "Seafood", "Cheese", "Breads", "Condiments", "Paper goods", "Cleaning supplies", "Smallwares", "Equipment"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Family\u2011owned, independent distributor with rapid disaster response", "Private\u2011label brands Copper Creek Cattle Company and Captain Frank\u2019s Seafood", "Custom\u2011cut steak program processed in Louisiana", "Fresh produce program backed by Fresh Concepts food\u2011safety guarantees", "Artisanal cheese program with The Rind Cheese Company"], "facts_used": ["Founded 1978 by Frank & Rosemary Spalitta -> /", "Family-owned, second generation leadership -> /about-us", "Headquarters Hammond, Louisiana -> /", "Broadline distributor of food and non-food items -> /", "Private label brands Copper Creek Cattle Company and Captain Frank\u2019s Seafood -> /", "Partnerships with Unipro Foodservice, Campbell Foodservice, ConAgra Foodservice, Rich Products Corporation, Pillsbury, Hormel, General Mills, Smithfield Foods, Fresh Concepts, The Rind Cheese Company -> /", "Serves Southeast Louisiana and Mississippi Gulf Coast -> /", "Facility near I-55/I-12 corridor -> /", "Disaster response: open next day after Ida and Katrina -> /", "Serves donut shops, coffee shops, Tex-Mex, Italian, Mediterranean, family dining, sandwich shops, seafood -> /", "Custom-cut steak program processed in Louisiana -> /", "Fresh produce program with Fresh Concepts -> /", "Artisanal cheese program with The Rind Cheese Company -> /", "Company slogan ''Large enough to serve, small enough to care'' -> /", "Paul Spalitta President/Owner -> /"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "A family-owned broadline distributor, providing the service you expect from an independent company, with the inventory and pricing you need to run any kind of restaurant or foodservice operation.", "founded_year": "1978", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='s-w-foods' AND approved AND profile IS NULL;
